const sl = (ms) => new Promise((r) => setTimeout(r, ms));
const log = [];
for (let i = 0; i < 90; i++) {
  if (document.querySelector('[data-testid="confirm-draft"]')) { log.push("confirm@" + i); break; }
  const c = document.querySelector('[data-testid="hero-choose"]');
  if (c && /輪到你/.test(document.body.innerText)) { log.push(c.dataset.hero); c.click(); await sl(900); continue; }
  await sl(800);
}
const cf = document.querySelector('[data-testid="confirm-draft"]');
return JSON.stringify({ log, confirm: !!cf, picks: (document.body.innerText.match(/出戰配置 \d\/5/) || [""])[0] });

const sl = (ms) => new Promise((r) => setTimeout(r, ms));
const r = document.querySelector('input[aria-label="重播時間軸"]');
if (!r) return JSON.stringify({ error: "no range" });
const set = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, "value").set;
const seen = new Map();
const pts = [];
const lo = Math.max(0, Number(r.min)), hi = Math.min(3000, Number(r.max)); for (let s = lo; s <= hi; s += 2) pts.push(s); pts.push(hi);
for (const s of pts) {
  set.call(r, String(s));
  r.dispatchEvent(new Event("input", { bubbles: true }));
  r.dispatchEvent(new Event("change", { bubbles: true }));
  await sl(25);
  for (const e of document.querySelectorAll('[data-testid="replay-event-text"]')) {
    const row = e.parentElement ? e.parentElement.innerText.trim() : e.innerText.trim();
    if (!seen.has(row)) seen.set(row, s);
  }
}
return JSON.stringify({ min: r.min, max: r.max, n: seen.size, rows: [...seen.keys()] });
